<script setup lang="ts">
import { computed, ref } from 'vue'
import type { ImportCandidate } from './importers'
import { formatFileSize, type ImportSource } from './importSources'
import { categoryPath, type LedgerSnapshot } from './ledger'
import { money } from './ledgerViewModels'
import UiIcon from './UiIcon.vue'
import CategoryIcon from './CategoryIcon.vue'
const props=defineProps<{ sources:ImportSource[]; candidates:ImportCandidate[]; snapshot:LedgerSnapshot; busy:boolean; saving:boolean; status:string; progress:number|null; selectedIds:string[] }>()
const emit=defineEmits<{ files:[files:File[]]; preview:[id:string,candidate?:ImportCandidate]; remove:[id:string]; retry:[id:string]; clear:[]; edit:[candidate:ImportCandidate]; confirm:[candidate:ImportCandidate]; 'confirm-selected':[]; 'update:selectedIds':[ids:string[]] }>()
const dragOver=ref(false),filterSource=ref(''),failedImages=ref(new Set<string>())
const visible=computed(()=>props.candidates.filter(item=>!filterSource.value||item.sourceId===filterSource.value))
const allSelected=computed(()=>visible.value.length>0&&visible.value.every(item=>props.selectedIds.includes(item.id)))
function filesChanged(event:Event){const input=event.target as HTMLInputElement;const files=[...(input.files||[])];input.value='';if(!props.busy&&files.length)emit('files',files)}
function drop(event:DragEvent){dragOver.value=false;if(!props.busy&&event.dataTransfer?.files.length)emit('files',[...event.dataTransfer.files])}
function select(id:string){emit('update:selectedIds',props.selectedIds.includes(id)?props.selectedIds.filter(value=>value!==id):[...props.selectedIds,id])}
function selectAll(){const ids=new Set(visible.value.map(item=>item.id));emit('update:selectedIds',allSelected.value?props.selectedIds.filter(id=>!ids.has(id)):[...new Set([...props.selectedIds,...ids])])}
function category(item:ImportCandidate){return props.snapshot.categories.find(category=>category.id===item.categoryId)}
function categoryLabel(item:ImportCandidate){return item.categoryId?categoryPath(props.snapshot.categories,item.categoryId).map(category=>category.name).join(' / ')||'未分类':item.categoryPath?.length?`建议：${item.categoryPath.join(' / ')}（待选择）`:'未分类'}
function date(item:ImportCandidate){if(!item.happenedAt)return '';const date=new Date(item.happenedAt);return Number.isNaN(date.getTime())?'':date.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
</script>
<template>
  <section class="page-content ocr-workbench">
    <header class="ocr-workbench-heading"><div><span class="ocr-eyebrow">识别 · 核对 · 入账</span><h2>让每张账单，成为清楚的记录。</h2><p>导入截图或账单文件，对照原件确认后再记入流水。</p></div><span class="ocr-local-badge"><UiIcon name="check" :size="14"/>在本机识别</span></header>
    <div class="ocr-upload-zone" :class="{'drag-over':dragOver,'is-busy':busy}" @dragover.prevent="dragOver=true" @dragleave.prevent="dragOver=false" @drop.prevent="drop"><span class="ocr-upload-symbol"><UiIcon name="scan" :size="31"/></span><div class="ocr-upload-copy"><h3>{{ dragOver?'松开即可添加文件':'添加账单原件' }}</h3><p>拖入文件，或选择手机相册中的账单截图</p><small>图片 · PDF · CSV · XLSX · TXT</small></div><div class="ocr-upload-actions"><label class="feature-button"><UiIcon name="camera" :size="17"/>拍摄小票<input type="file" accept="image/*" capture="environment" :disabled="busy" @change="filesChanged"/></label><label class="feature-button accent"><UiIcon name="plus" :size="17"/>{{ sources.length?'继续添加':'选择截图或文件' }}<input type="file" multiple accept="image/*,.pdf,.csv,.xlsx,.txt" :disabled="busy" @change="filesChanged"/></label></div></div>
    <section v-if="sources.length" class="ocr-sources-section"><header><div><h3>账单原件 <span>{{ sources.length }}</span></h3><p>点击缩略图查看原件；识别失败的文件也可以预览。</p></div><button type="button" class="feature-text-button" :disabled="busy||saving" @click="emit('clear')">清空本次导入</button></header><div class="ocr-source-grid"><article v-for="source in sources" :key="source.id" class="ocr-source-card" :class="{failed:source.status==='error'}"><button type="button" class="ocr-source-open" :aria-label="`预览原件 ${source.name}`" @click="emit('preview',source.id)"><span v-if="source.kind==='image'&&!failedImages.has(source.id)" class="ocr-source-thumbnail"><img :src="source.url" :alt="source.name" @error="failedImages.add(source.id)"/><i><UiIcon name="expand" :size="14"/></i></span><span v-else class="ocr-source-document"><UiIcon :name="source.kind==='table'?'table':source.kind==='image'?'image':'file'" :size="27"/><small>{{ source.name.split('.').at(-1)?.toUpperCase() }}</small></span><span class="ocr-source-copy"><b>{{ source.name }}</b><small>{{ formatFileSize(source.file.size) }} · {{ source.status==='queued'?'等待识别':source.status==='processing'?'正在识别…':source.status==='error'?'识别失败':`识别到 ${source.candidateCount} 条` }}</small><span v-if="source.error" class="ocr-source-error">{{ source.error }}</span><span v-else class="ocr-source-preview-hint">点击预览原件<UiIcon name="expand" :size="11"/></span></span></button><div class="ocr-source-actions"><button v-if="source.status==='error'" type="button" aria-label="重试识别此文件" title="重试识别" :disabled="busy" @click="emit('retry',source.id)"><UiIcon name="sync" :size="14"/></button><button type="button" :aria-label="`移除文件 ${source.name}`" title="移除文件" :disabled="busy||saving" @click="emit('remove',source.id)"><UiIcon name="close" :size="14"/></button></div></article></div></section>
    <div v-if="busy" class="ocr-processing" role="status" aria-live="polite"><span class="ocr-processing-icon"><UiIcon name="scan" :size="20"/></span><div><b>{{ status }}</b><progress v-if="progress!==null" :value="progress" max="1"></progress><small>{{ progress!==null?`${Math.round(progress*100)}% · `:'' }}处理期间可打开原件查看</small></div></div>
    <section v-if="candidates.length" class="ocr-results-section"><header class="ocr-results-heading"><div><h3>待确认流水 <span>{{ candidates.length }}</span></h3><p>点开卡片核对详情，编辑后可先保存修改，再统一入账。</p></div><label v-if="sources.length>1" class="ocr-source-filter"><UiIcon name="filter" :size="14"/><select v-model="filterSource" aria-label="按来源文件筛选"><option value="">全部来源文件</option><option v-for="source in sources" :key="source.id" :value="source.id">{{ source.name }}</option></select></label></header><div class="ocr-selection-bar"><label><input type="checkbox" :checked="allSelected" :disabled="saving" @change="selectAll"/>{{ allSelected?'取消全选':'全选当前列表' }}</label><small>已选择 {{ selectedIds.length }} 条</small><button type="button" class="feature-button accent" :disabled="busy||saving||!selectedIds.length" @click="emit('confirm-selected')"><UiIcon name="check" :size="15"/>{{ saving?'正在入账…':`确认入账 ${selectedIds.length} 条` }}</button></div><div class="ocr-result-list"><article v-for="item in visible" :key="item.id" class="ocr-result-card" :class="{selected:selectedIds.includes(item.id)}"><label class="ocr-result-checkbox"><input type="checkbox" :checked="selectedIds.includes(item.id)" :aria-label="`选择 ${item.title||'未命名流水'}`" :disabled="saving" @change="select(item.id)"/></label><button type="button" class="ocr-result-main" @click="emit('edit',item)"><span class="ocr-result-category-icon"><CategoryIcon :name="category(item)?.icon" :category-name="category(item)?.name" :flow-type="item.kind||'expense'" :color="category(item)?.color||'#7295c6'" :size="22"/></span><span class="ocr-result-copy"><strong>{{ item.title||'待补充名称' }}</strong><small v-if="item.merchant&&item.merchant!==item.title">{{ item.merchant }}</small><span class="ocr-result-meta"><span :class="{warning:!date(item)}"><UiIcon name="calendar" :size="12"/>{{ date(item)||'日期待补充' }}</span><span>{{ item.paymentMethod||'支付渠道待确认' }}</span></span></span><span class="ocr-result-amount" :class="{income:item.kind==='income',warning:!item.amount}"><small>{{ item.kind==='income'?'收入':'支出' }}</small><b>{{ item.amount?money(item.amount):'待补金额' }}</b><UiIcon name="chevron" :size="15"/></span></button><div class="ocr-result-footer"><span class="ocr-result-category">{{ categoryLabel(item) }}</span><span v-if="item.offsetEnabled" class="ocr-result-subsidy"><UiIcon name="check" :size="12"/>{{ item.paymentMethod==='公司补贴'?'公司补贴':'关联抵扣' }} {{ item.offsetRatio??100 }}%</span><button v-if="item.sourceId" type="button" class="ocr-result-source" :title="item.sourceName" @click="emit('preview',item.sourceId,item)"><UiIcon name="file" :size="12"/><span>{{ item.sourceName }}<template v-if="item.sourcePage"> · 第 {{ item.sourcePage }} 页</template><template v-if="item.sourceRow"> · 第 {{ item.sourceRow }} 行</template></span><UiIcon name="expand" :size="11"/></button><button type="button" class="feature-text-button" @click="emit('edit',item)">编辑</button><button type="button" class="ocr-result-confirm" :disabled="saving||busy" @click="emit('confirm',item)">确认入账<UiIcon name="check" :size="12"/></button></div></article><div v-if="!visible.length" class="ocr-no-results">该文件没有待确认流水，可以切换查看其他文件。</div></div></section>
    <div v-else-if="!busy" class="ocr-import-empty"><span><UiIcon :name="sources.length?'check':'image'" :size="30"/></span><h3>{{ sources.length?(sources.some(source=>source.status==='error')?'原件已保留，可预览后重试':'本次没有待确认流水'):'从一张截图开始' }}</h3><p>{{ sources.length?'可继续添加文件；原件不会因为入账或识别失败而消失。':'支持支付详情、美团订单、大象企业餐账单与账单文件。' }}</p><div v-if="!sources.length"><span>选择原件</span><UiIcon name="chevron" :size="12"/><span>核对信息</span><UiIcon name="chevron" :size="12"/><span>确认入账</span></div></div>
  </section>
</template>
